SELECT "__time" AS "time", "__c0" AS "sensor.ENERGY.Total", "__c1" AS "sensor.ENERGY.Total" FROM (SELECT COALESCE(sub0.time, sub1.time) AS "__time", (sub0.value - lag(sub0.value) OVER (ORDER BY sub0.time)) AS "__c0", (sub1.value) AS "__c1" FROM (SELECT time_bucket('1d', "time", 'Europe/Berlin') AS "time", last("sensor.ENERGY.Total", "time") AS value FROM "device:reH7pvpfRwSZl4HcFo9i9A_service:l4BYIMoKRsWdzxbC44awUA" WHERE "time" >= time_bucket('1d', time_bucket('1d', now() - interval '7d', 'Europe/Berlin') - interval '1 microsecond', 'Europe/Berlin') GROUP BY 1 ORDER BY 1 ASC) sub0 FULL OUTER JOIN (SELECT time_bucket('1d', "time", 'Europe/Berlin') AS "time", avg("sensor.ENERGY.Total") AS value FROM "device:reH7pvpfRwSZl4HcFo9i9A_service:l4BYIMoKRsWdzxbC44awUA" WHERE "time" >= time_bucket('1d', time_bucket('1d', now() - interval '7d', 'Europe/Berlin') - interval '1 microsecond', 'Europe/Berlin') GROUP BY 1 ORDER BY 1 ASC) sub1 on sub0.time = sub1.time) d WHERE "__time" >= time_bucket('1d', now() - interval '7d', 'Europe/Berlin') ORDER BY 1 DESC